begin;
alter table workshop_private.catalog75 add column if not exists unavailable boolean not null default false;
create or replace function public.workshop_stock76(p_id uuid,p_state boolean,p_rev int) returns void language plpgsql security definer set search_path='' as $$
declare a jsonb;k text;begin a:=workshop_private.actor();if not coalesce((a->>'admin')::bool,false) then raise exception 'Réservé à l’administrateur';end if;
select section into strict k from workshop_private.catalog75 where id=p_id;
update workshop_private.catalog75_rev set rev=rev+1 where section=k and rev=p_rev;if not found then raise exception 'Catalogue modifié, rouvre l’éditeur';end if;
update workshop_private.catalog75 set unavailable=p_state where id=p_id;end $$;
create or replace function public.workshop_catalog76(p_section text,p_known int default -1) returns jsonb language plpgsql security definer set search_path='' as $$
declare d jsonb;begin d:=public.workshop_catalog75(p_section,p_known);
if jsonb_typeof(d->'items')='array' then d:=d||jsonb_build_object('items',(select coalesce(jsonb_agg(x||jsonb_build_object('unavailable',c.unavailable) order by coalesce(f.n,0) desc,c.position,c.id),'[]') from jsonb_array_elements(d->'items') x join workshop_private.catalog75 c on c.id::text=x->>'id' left join (select item->>'id' id,count(distinct o.id) n from public.workshop_order_requests o cross join lateral jsonb_array_elements(o.items) item where o.deleted_at is null group by 1) f on f.id=c.id::text));end if;return d;end $$;
create or replace function workshop_private.guard_order76() returns trigger language plpgsql security definer set search_path='' as $$
declare x jsonb;prior jsonb:='[]';n numeric;begin if tg_op='UPDATE' then prior:=old.items;end if;
for x in select value from jsonb_array_elements(new.items) loop
select coalesce(sum((v->>'quantity')::numeric),0) into n from jsonb_array_elements(prior) v where v->>'id'=x->>'id' and v->>'label'=x->>'label';
if (x->>'quantity')::numeric>n and (exists(select 1 from workshop_private.catalog75 c where c.unavailable and (c.id::text=x->>'id' or lower(trim(c.name))=lower(trim(x->>'label')))) or exists(select 1 from workshop_private.oil_catalog72 o cross join lateral jsonb_array_elements(o.items) t where t->>'unavailable'='true' and (lower(x->>'label')=lower((t->>'name')||case when coalesce(t->>'pack','')='' then '' else ' ('||(t->>'pack')||')' end) or (t->>'kind'='tank' and starts_with(lower(x->>'label'),lower((t->>'name')||' — livraison en cuve de ')))))) then raise exception 'Produit en rupture : ajout à la commande impossible.';end if;end loop;
return new;end $$;
drop trigger if exists guard_order76 on public.workshop_order_requests;
create trigger guard_order76 before insert or update of items on public.workshop_order_requests for each row execute function workshop_private.guard_order76();
create or replace function workshop_private.refresh_freq76() returns trigger language plpgsql security definer set search_path='' as $$begin update workshop_private.catalog75_rev set rev=rev+1;return null;end $$;
drop trigger if exists freq76 on public.workshop_order_requests;create trigger freq76 after insert or update of items,deleted_at or delete on public.workshop_order_requests for each statement execute function workshop_private.refresh_freq76();
create table if not exists workshop_private.common76(id uuid primary key default gen_random_uuid(),title text not null,created_at timestamptz default now());
create table if not exists workshop_private.steps76(id uuid primary key default gen_random_uuid(),task uuid references workshop_private.common76 on delete cascade,position int,label text not null,done boolean not null default false);
alter table workshop_private.common76 enable row level security;alter table workshop_private.steps76 enable row level security;
revoke all on workshop_private.common76,workshop_private.steps76 from public,anon,authenticated;
create or replace function public.workshop_common76() returns jsonb language plpgsql security definer set search_path='' as $$begin perform workshop_private.actor();return(select coalesce(jsonb_agg(to_jsonb(c)||jsonb_build_object('steps',(select jsonb_agg(to_jsonb(s) order by position) from workshop_private.steps76 s where s.task=c.id)) order by created_at desc),'[]') from workshop_private.common76 c);end $$;
create or replace function public.workshop_common_create76(p_title text,p_lines text[]) returns uuid language plpgsql security definer set search_path='' as $$declare a jsonb;k uuid;begin a:=workshop_private.actor();if not coalesce((a->>'manager')::bool,false) then raise exception 'Réservé aux gestionnaires';end if;if length(trim(coalesce(p_title,''))) not between 1 and 160 or coalesce(cardinality(p_lines),0) not between 1 and 100 or exists(select 1 from unnest(p_lines) x where length(trim(coalesce(x,''))) not between 1 and 300) then raise exception 'Titre ou liste invalide';end if;insert into workshop_private.common76(title) values(trim(p_title)) returning id into k;insert into workshop_private.steps76(task,position,label) select k,ord,trim(x) from unnest(p_lines) with ordinality t(x,ord);return k;end $$;
create or replace function public.workshop_common_tick76(p_id uuid,p_done boolean) returns void language plpgsql security definer set search_path='' as $$declare a jsonb;begin a:=workshop_private.actor();if a->>'role'='guest' then raise exception 'Lecture seule';end if;update workshop_private.steps76 set done=p_done where id=p_id;if not found then raise exception 'Ligne introuvable';end if;end $$;
revoke all on function public.workshop_common76(),public.workshop_common_create76(text,text[]),public.workshop_common_tick76(uuid,boolean),public.workshop_stock76(uuid,boolean,int),public.workshop_catalog76(text,int) from public,anon;
grant execute on function public.workshop_common76(),public.workshop_common_create76(text,text[]),public.workshop_common_tick76(uuid,boolean),public.workshop_stock76(uuid,boolean,int),public.workshop_catalog76(text,int) to authenticated;
do $$declare k text:='Freins, transmissions, roulements';begin insert into workshop_private.catalog75_rev values(k,1) on conflict do nothing;if found then insert into workshop_private.catalog75(section,name,photo,position) select k,v->>'name',decode(v->>'photo','base64'),ord from jsonb_array_elements($products$[{"name": "ROUL.TOILE EMERI G.80 STATION", "photo": ""}, {"name": "LIQ.FREIN BREMBO DOT 4 LV 20L", "photo": ""}, {"name": "NETTOYANT DEGRAISSANT 5L", "photo": ""}, {"name": "NETTOYANT DEGRAISSANT 20L", "photo": ""}, {"name": "BIDON PULVE.1L NETTOYANT FREIN", "photo": ""}, {"name": "KIT JOINT PR PULVERISATEUR CODE 2177103", "photo": ""}, {"name": "BIO NET DEGRAISSANT 20L POUR FONTAINE BARDAHL", "photo": ""}, {"name": "4 PASTILLES BIO TAB POUR FONTAINE BARDAHL", "photo": ""}, {"name": "2 FILTRES POUR FONTAINE BARDAHL", "photo": ""}, {"name": "100COLLIERS/SOUFFLET PM", "photo": ""}, {"name": "50COLLIERS/SOUFFLET GM", "photo": ""}, {"name": "AEROS.MONT.SOUF.TRANSMIS.250ML", "photo": ""}, {"name": "FREIN FILET MOYEN BLEU 50ML", "photo": ""}, {"name": "FREIN FILET FORT ROUGE 50ML", "photo": ""}, {"name": "GRAISSE HT FREIN BELLVL 150G", "photo": ""}, {"name": "BIDON 1L DEGRIPPANT ATELIER", "photo": ""}, {"name": "PULVERISATEUR DEGRIPPANT ATEL.", "photo": ""}, {"name": "CONE ARTICUL.PM/MONT.SOUFFLETS", "photo": ""}, {"name": "CONE ARTICUL.GM/MONT.SOUFFLETS", "photo": ""}, {"name": "OUTIL MONT.SOUFF.CREMAILL DG41", "photo": ""}]$products$::jsonb) with ordinality t(v,ord);end if;end $$;create or replace function public.workshop_oil_frequency76() returns jsonb language plpgsql security definer set search_path='' as $$begin perform workshop_private.actor_before30();return (select coalesce(jsonb_object_agg(label,n),'{}') from (select split_part(item->>'label',' — livraison en cuve de ',1) label,count(distinct o.id) n from public.workshop_order_requests o cross join lateral jsonb_array_elements(o.items) item where o.deleted_at is null and item->>'label' is not null group by 1) f);end $$;
revoke all on function public.workshop_oil_frequency76() from public,anon;
grant execute on function public.workshop_oil_frequency76() to authenticated;notify pgrst,'reload schema';commit;